Lemma RHEAP_init_proof : forall (m : mem) (auxv : word),
  (forall a : word, 0xecfc8 <= bv_unsigned a < 0xed370 -> m a = None) ->      (* [comment removed for export] *)
  (forall a : word, RVMLOCKC <= bv_unsigned a < RVMLOCKC + 4 -> m a = None) ->   (* [comment removed for export] *)
  rw_cells rsegs m 0xece53 [C1 (Z_to_bv 8 0)] ->                              (* [comment removed for export] *)
  rw_cells rsegs m 0xece58 [C8 auxv] ->                                        (* [comment removed for export] *)
  rw_cells rsegs m 0xece80 [C8 (Z_to_bv 64 4096)] ->                           (* [comment removed for export] *)
  rw_cells rsegs m 0xb9e20 [C8 (Z_to_bv 64 0xece30)] ->                        (* [comment removed for export] *)
  rw_cells rsegs m 0xece30 [C8 (Z_to_bv 64 canary_val)] ->                     (* [comment removed for export] *)
  mem_inv rsegs m ->
  RHEAP (ps_init (reservedZ rsegs)) [] m
